const c = $input.first().json;
const runId = $('Case Input').item.json.run_id;
const caseId = $('Case Input').item.json.case_id;
let ctx = c.context_messages;
if (typeof ctx === 'string') { try { ctx = JSON.parse(ctx); } catch (e) { ctx = []; } }
if (!Array.isArray(ctx)) ctx = [];
const sessionId = 'retrieval-' + runId + '-' + caseId;
// Multi-turn cases: fold prior turns into ONE prompt. Replaying turns as separate
// agent calls accumulates tool outputs in session memory and overflows the context
// window (observed: 3M tokens by turn 3 on a transcript-heavy case).
let chatInput = c.prompt;
if (ctx.length) {
  const numbered = ctx.map((m, i) => (i + 1) + '. ' + String(m)).join('\n');
  chatInput = 'Earlier in this conversation, the user said:\n' + numbered + '\n\nCurrent question: ' + c.prompt;
}
return [{ json: { chatInput: chatInput, is_final: true, sessionId: sessionId, slug: c.slug } }];

const items = $input.all();
const c = $('Load Case').item.json;
const runId = $('Case Input').item.json.run_id;
const caseId = $('Case Input').item.json.case_id;
const final = items[items.length - 1].json;
let status = 'pending';
let answer = '';
let called = [];
let steps = [];
if (final && final.error) {
  status = 'error';
  answer = typeof final.error === 'string' ? final.error : JSON.stringify(final.error);
} else {
  if (typeof final.output === 'string') answer = final.output;
  else if (final.output !== undefined) answer = JSON.stringify(final.output);
  else answer = JSON.stringify(final);
  if (Array.isArray(final.tools_used)) called = final.tools_used;
  if (Array.isArray(final.intermediateSteps)) steps = final.intermediateSteps;
  if (!answer) status = 'error';
}
const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const calledN = [];
for (const t of called) { const n = norm(t); if (!calledN.includes(n)) calledN.push(n); }
for (const s of steps) { const t = s && s.action && s.action.tool; if (t) { const n = norm(t); if (!calledN.includes(n)) calledN.push(n); } }

const metaOf = (row, contentKey) => {
  if (row.metadata && typeof row.metadata === 'object') return row.metadata;
  const m = {};
  for (const k of Object.keys(row)) {
    if (k === contentKey || k === 'metadata' || k === 'score') continue;
    const v = row[k];
    if (v == null || typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') m[k] = v;
  }
  return m;
};

const unwrapRow = (row) => {
  if (!row || typeof row !== 'object') return null;
  if (row.document && typeof row.document.pageContent === 'string') {
    return { content: row.document.pageContent, metadata: row.document.metadata || {}, score: row.score ?? null };
  }
  if (typeof row.pageContent === 'string') return { content: row.pageContent, metadata: metaOf(row, 'pageContent'), score: row.score ?? null };
  if (typeof row.content === 'string') return { content: row.content, metadata: metaOf(row, 'content'), score: row.score ?? null };
  if (typeof row.session_summary === 'string' || typeof row.profile_summary === 'string') {
    return { content: row.session_summary || row.profile_summary || '', metadata: metaOf(row, 'session_summary'), score: null };
  }
  return null;
};

const compressObs = (obs) => {
  if (obs == null) return [];
  let parsed;
  try { parsed = JSON.parse(String(obs)); } catch (e) { return [{ content: String(obs).slice(0, 1200), metadata: {}, score: null }]; }
  const outer = Array.isArray(parsed) ? parsed : [parsed];
  const rows = [];
  for (const item of outer) {
    const blocks = item && Array.isArray(item.response) ? item.response : [item];
    for (const b of blocks) {
      let candidate = b;
      if (b && b.type === 'text' && typeof b.text === 'string') {
        try { candidate = JSON.parse(b.text); } catch (e) { candidate = { content: b.text }; }
      }
      const row = unwrapRow(candidate);
      if (row) rows.push(row);
      if (rows.length >= 10) break;
    }
    if (rows.length >= 10) break;
  }
  return rows.map(r => ({ content: r.content.slice(0, 1200), metadata: r.metadata, score: r.score }));
};

const baseUrl = String($vars.instance_url || 'https://darwin-staging.app.n8n.cloud').replace(/\/$/, '');
const trimmed = steps.slice(0, 25).map(s => ({
  tool: s && s.action && s.action.tool ? norm(s.action.tool) : null,
  input: s && s.action ? JSON.stringify(s.action.toolInput ?? null).slice(0, 2000) : null,
  rows: compressObs(s ? s.observation : null)
}));
return [{ json: {
  run_id: runId,
  case_id: caseId,
  case_slug: c.slug,
  status: status,
  agent_output: answer.slice(0, 8000),
  called_tools: calledN,
  raw_steps: trimmed,
  execution_url: baseUrl + '/workflow/' + $workflow.id + '/executions/' + $execution.id
} }];

const r = $input.first().json;
const c = $('Load Case').item.json;
if (r.status === 'error') return [{ json: Object.assign({}, r, { metrics: { reason: 'agent run errored — see execution link' } }) }];

const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const normText = s => String(s).toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
const TOOL_SOURCE = { session_search: 'sessions', search: 'sessions', get_session: 'sessions', get_sessions: 'sessions', slack_store: 'slack', forum_store: 'forum', plain: 'plain', gong: 'gong', get_jobs: 'jobs', get_opportunities: 'opportunities' };

const hits = [];
for (const s of (r.raw_steps || [])) {
  if (!s.tool || !(s.tool in TOOL_SOURCE)) continue;
  const source = TOOL_SOURCE[s.tool];
  for (const row of (s.rows || [])) {
    const m = row.metadata || {};
    const str = v => (typeof v === 'string' ? v : null);
    const num = v => (typeof v === 'number' ? v : null);
    const content = String(row.content || '');
    const h = {
      rank: hits.length + 1, source: source,
      snippet: content.length > 300 ? content.slice(0, 300) + '...' : content,
      quote: null, attribution: null, project_name: null,
      timestamp: null, title: null, deep_link: null, created_at: null,
      score: row.score ?? null, id: String(hits.length + 1), group_key: null
    };
    if (source === 'sessions') { h.id = str(m.session_id) ?? str(m.id) ?? h.id; h.group_key = str(m.session_id) ?? str(m.id); h.timestamp = num(m.start); h.attribution = str(m.participant_name); h.created_at = str(m.created_at); }
    else if (source === 'gong') { h.id = str(m.call_id) ?? h.id; h.group_key = str(m.call_id); h.title = str(m.title); h.deep_link = str(m.url); h.created_at = str(m.date); }
    else if (source === 'forum') { h.id = str(m.post_id) ?? h.id; h.group_key = m.topic_id ? 'topic ' + m.topic_id : null; h.title = str(m.topic_title); h.deep_link = str(m.post_url); }
    else if (source === 'plain') { h.id = str(m.thread_id) ?? h.id; h.group_key = str(m.thread_id); h.title = str(m.thread_title); }
    else if (source === 'slack') { h.id = str(m.ts) ?? h.id; h.group_key = str(m.ts); h.deep_link = str(m.url); }
    else { h.id = str(m.id) ?? h.id; h.group_key = str(m.id); h.title = str(m.theme); }
    hits.push(h);
  }
}

let expected = c.expected || {};
if (typeof expected === 'string') { try { expected = JSON.parse(expected); } catch (e) { expected = {}; } }
const requiredFields = Array.isArray(c.required_fields) ? c.required_fields : [];
const expectedTools = (Array.isArray(c.expected_tools) ? c.expected_tools : []).map(norm);

const hitText = h => normText([h.quote, h.snippet, h.title].filter(Boolean).join(' '));
const isSess = (h, id) => h.source === 'sessions' && (h.group_key === id || h.id === id);

const expSources = expected.sources || [];
const expSessions = expected.session_ids || [];
const absentIds = expected.absent_session_ids || [];
const expQuotes = expected.quotes || [];

const distinctSources = new Set(hits.map(h => h.source)).size;
const sourceRecall = expSources.length ? expSources.filter(s => hits.some(h => h.source === s)).length / expSources.length : null;
const sessionRecall = expSessions.length ? expSessions.filter(id => hits.some(h => isSess(h, id))).length / expSessions.length : null;
const absentCompliance = absentIds.length ? 1 - absentIds.filter(id => hits.some(h => isSess(h, id))).length / absentIds.length : null;
const quoteRecall = expQuotes.length ? expQuotes.filter(q => hits.some(h => hitText(h).includes(normText(q)))).length / expQuotes.length : null;

let mrr = null;
if (expSessions.length + expQuotes.length + expSources.length > 0) {
  mrr = 0;
  for (const h of hits) {
    const match = expSessions.some(id => isSess(h, id)) || expQuotes.some(q => hitText(h).includes(normText(q))) || expSources.includes(h.source);
    if (match) { mrr = 1 / h.rank; break; }
  }
}

const top5 = hits.slice(0, 5);
const fieldCompleteness = requiredFields.length && top5.length
  ? top5.filter(h => requiredFields.every(f => h[f] !== null && h[f] !== undefined && h[f] !== '')).length / top5.length
  : null;

const groupDiversity = new Set(hits.map(h => h.group_key).filter(Boolean)).size;

const called = (r.called_tools || []).map(norm);
const routing = expectedTools.length ? expectedTools.some(t => called.includes(t)) : null;

const answer = normText(r.agent_output || '');
const answerQuoteRecall = expQuotes.length ? expQuotes.filter(q => answer.includes(normText(q))).length / expQuotes.length : null;
const answerSessionRecall = expSessions.length ? expSessions.filter(id => String(r.agent_output || '').includes(id)).length / expSessions.length : null;

const layers = [];
if (routing !== null) layers.push(routing);
if (answerQuoteRecall !== null && requiredFields.length) layers.push(answerQuoteRecall > 0);
if (hits.length) {
  if (expSources.length) layers.push(sourceRecall === 1);
  if (expSessions.length) layers.push(sessionRecall > 0);
  if (absentIds.length) layers.push(absentCompliance === 1);
  if (expected.min_sources) layers.push(distinctSources >= expected.min_sources);
  if (requiredFields.length) layers.push(fieldCompleteness === 1);
}
const status = layers.length && layers.every(Boolean) ? 'pass' : 'fail';

const zeroTools = [];
for (const s of (r.raw_steps || [])) {
  if (s.tool && Array.isArray(s.rows) && s.rows.length === 0 && (s.tool in TOOL_SOURCE)) zeroTools.push(s.tool);
}
let reason = '—';
if (status !== 'pass') {
  if (routing === false) {
    reason = 'never called ' + (c.expected_tools || []).join(' / ') + ' (used: ' + ((r.called_tools || []).join(', ') || 'none') + ')';
  } else if (!(r.called_tools || []).length) {
    reason = 'agent answered without calling any tool';
  } else if (!hits.length) {
    reason = 'no retrieval hits captured' + (zeroTools.length ? ' — ' + zeroTools.join(', ') + ' returned 0 rows' : '');
  } else if (absentIds.length && absentCompliance !== null && absentCompliance < 1) {
    const leaked = absentIds.filter(id => hits.some(h => isSess(h, id)));
    reason = 'unapproved session surfaced (' + leaked.length + ' of ' + absentIds.length + ' guarded)';
  } else if (expSources.length && sourceRecall !== null && sourceRecall < 1) {
    const missing = expSources.filter(s => !hits.some(h => h.source === s));
    const zero = zeroTools.filter(t => missing.includes(TOOL_SOURCE[t]));
    reason = 'no hits from expected source: ' + missing.join(', ') + (zero.length ? ' — ' + zero.join(', ') + ' returned 0 rows' : '');
  } else if (expSessions.length && sessionRecall === 0) {
    reason = 'none of the ' + expSessions.length + ' expected sessions surfaced in ' + hits.length + ' hits';
  } else if (expected.min_sources && distinctSources < expected.min_sources) {
    reason = 'too few sources: ' + distinctSources + ' < ' + expected.min_sources + ' required';
  } else if (requiredFields.length && fieldCompleteness !== null && fieldCompleteness < 1) {
    const missingFields = requiredFields.filter(f => hits.some(h => h[f] == null || h[f] === ''));
    reason = 'hits missing required fields: ' + (missingFields.length ? missingFields.join(', ') : requiredFields.join(', '));
  } else if (answerQuoteRecall === 0 && requiredFields.length) {
    reason = 'answer missing expected quotes';
  } else {
    reason = 'see metrics';
  }
}

return [{ json: Object.assign({}, r, {
  status: status,
  metrics: {
    reason: reason,
    routing: routing,
    answer_quote_recall: answerQuoteRecall,
    answer_session_recall: answerSessionRecall,
    retrieval_hits: hits.length,
    retrieval: {
      source_recall: sourceRecall,
      distinct_sources: distinctSources,
      session_recall: sessionRecall,
      absent_compliance: absentCompliance,
      quote_recall: quoteRecall,
      mrr: mrr,
      field_completeness: fieldCompleteness,
      group_diversity: groupDiversity
    }
  }
}) }];
